export const DEFAULT_PROXY_URL = "https://duelagents.com/v1";
export const DASHBOARD_URL = "https://duelagents.com/dashboard/settings";
export const KEY_DOCS_URL = "https://duelagents.com/dashboard/settings";
/** duel_ + 8-char prefix + _ + 32-char base62 secret */
const API_KEY_PATTERN = /^duel_[0-9a-zA-Z]{8}_[0-9a-zA-Z]{32}$/;
/** Returns true only for a well formed `duel_<prefix>_<secret>` key. */
export function validateApiKey(plaintext) {
    if (!plaintext || typeof plaintext !== "string")
        return false;
    return API_KEY_PATTERN.test(plaintext.trim());
}
export function requireApiKey(input, label = "DUEL_API_KEY") {
    const trimmed = input?.trim() ?? "";
    if (!validateApiKey(trimmed)) {
        throw new Error(`Invalid or missing ${label}. Get a Duel API key at ${DASHBOARD_URL}. Format: duel_<prefix>_<secret>`);
    }
    return trimmed;
}
/** Resolve the proxy URL from env, validated and without a trailing slash. */
export function getProxyUrl() {
    const fromEnv = process.env.DUEL_PROXY_URL?.trim() ||
        process.env.NEXT_PUBLIC_PROXY_URL?.trim();
    const url = fromEnv || DEFAULT_PROXY_URL;
    if (!/^https?:\/\/.+/i.test(url)) {
        throw new Error(`Invalid DUEL_PROXY_URL "${url}". Expected an http(s) URL (trailing slashes are stripped automatically).`);
    }
    return url.replace(/\/$/, "");
}
/**
 * Build the environment variables a given install target expects. The key is
 * validated first, so callers can rely on the returned values being well formed.
 */
export function getEnvForTarget(target, apiKey, proxyUrl = getProxyUrl()) {
    requireApiKey(apiKey);
    switch (target) {
        case "claude-code":
            return {
                ANTHROPIC_BASE_URL: proxyUrl,
                ANTHROPIC_API_KEY: apiKey,
                DUEL_API_KEY: apiKey,
            };
        case "codex":
        case "openai-compat":
            return {
                OPENAI_BASE_URL: proxyUrl,
                OPENAI_API_KEY: apiKey,
                DUEL_API_KEY: apiKey,
            };
        case "cursor":
            return {
                DUEL_API_KEY: apiKey,
                DUEL_PROXY_URL: proxyUrl,
            };
        case "openclaw":
            return {
                DUEL_API_KEY: apiKey,
                DUEL_PROXY_URL: proxyUrl,
            };
        default:
            return { DUEL_API_KEY: apiKey, DUEL_PROXY_URL: proxyUrl };
    }
}
/**
 * Build the OpenClaw provider patch. The API key is referenced as
 * `${DUEL_API_KEY}` and never written into the `env` block as plaintext.
 */
export function buildOpenClawPatch(apiKey, proxyUrl = getProxyUrl()) {
    requireApiKey(apiKey);
    return {
        models: {
            mode: "merge",
            providers: {
                duel: {
                    baseUrl: proxyUrl,
                    apiKey: "${DUEL_API_KEY}",
                    api: "openai-completions",
                    models: [
                        {
                            id: "duel-auto",
                            name: "Duel Auto",
                            reasoning: false,
                            input: ["text"],
                            cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
                            contextWindow: 200000,
                            maxTokens: 8192,
                        },
                    ],
                },
            },
        },
        agents: {
            defaults: {
                model: { primary: "duel/duel-auto" },
                models: {
                    "duel/duel-auto": { alias: "Duel" },
                },
            },
        },
        env: {
            DUEL_PROXY_URL: proxyUrl,
        },
    };
