      const res = await checkConnectivity(KEY, "https://proxy.test/v1");
      assert.equal(res.ok, false);
      assert.equal(res.status, "unreachable");
      assert.equal(res.httpStatus, undefined);
      assert.match(res.message, /boom/);
    },
  );

  await withFetch(
    async () => new Response(null, { status: 500 }),
    async () => {
      const res = await checkConnectivity(KEY, "https://proxy.test/v1");
      assert.equal(res.ok, false);
      assert.equal(res.status, "unreachable");
      assert.equal(res.httpStatus, 500);
      assert.match(res.message, /500/);
    },
  );
});
